// Anyone can find a URL; only the key holder gets to spend API credits.
const q = $input.first().json.query || {};
if (q.k !== 'moon-2026') return [];
const dj = String(q.dj || '').toLowerCase().trim();
if (!dj) return [];
return [{ json: { dj } }];

// Load the DJ profile: explicit ?dj= from the webhook, or whoever's daypart
// it is when the schedule trigger fired.
// Dayparts (America/Phoenix, hours inclusive): Burt 6-11, Canyon Jack 12-17, Kaley 18-23.
const DAYPARTS = [
  { dj: 'burt', from: 6, to: 11 },
  { dj: 'canyonjack', from: 12, to: 17 },
  { dj: 'kaley', from: 18, to: 23 },
];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const roster = JSON.parse(buf.toString('utf8'));

let djId = '';
try { djId = $('Check the key').first().json.dj || ''; } catch (e) {}
if (!djId) {
  const hour = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' })).getHours();
  const slot = DAYPARTS.find((s) => hour >= s.from && hour <= s.to);
  if (!slot) return [];   // no DJ on duty this hour — end quietly
  djId = slot.dj;
}

const profile = (roster.djs || {})[djId];
if (!profile) throw new Error('No DJ named "' + djId + '" in the roster');
if (profile.active === false) throw new Error('DJ "' + djId + '" is marked inactive in the roster');
return [{ json: { djId, profile } }];

// The DJ Engine fact sheet: the same verified-facts machinery as Marcus's
// workflow, but the persona, length, voice and delivery come from the DJ
// Roster profile — one engine, many DJs.
const sd = $getWorkflowStaticData('global');
const sel = $('Select the DJ').first().json;
const profile = sel.profile;
const djId = sel.djId;
// Daypart shifts (mirror of Select the DJ). A DJ with a slot gets the
// per-shift song quota and the daypart topic rules below.
const DAYPARTS = { burt: { from: 6, to: 11 }, canyonjack: { from: 12, to: 17 }, kaley: { from: 18, to: 23 } };
const slot = DAYPARTS[djId] || null;
sd.djs = sd.djs || {};
const mem = sd.djs[djId] = sd.djs[djId] || {};

// --- time ---
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const today = phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate());
const daysN = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const weekday = daysN[phx.getDay()];
const hour = phx.getHours();
const clock = (((hour + 11) % 12) + 1) + ':' + pad(phx.getMinutes()) + ' ' + (hour >= 12 ? 'PM' : 'AM');
const bucket = hour < 5 ? 'overnight' : hour < 7 ? 'early morning' : hour < 9 ? 'morning drive' : hour < 11 ? 'late morning' : hour < 14 ? 'midday' : hour < 17 ? 'afternoon' : hour < 19 ? 'late afternoon' : hour < 22 ? 'evening' : 'late night';

// --- weather: NWS current observation, real numbers or nothing ---
let wx = null;
try {
  const o = $('Weather for DJ2').first().json.currentobservation;
  if (o && o.Temp && o.Weather) wx = { temp: parseInt(o.Temp, 10), cond: String(o.Weather) };
} catch (e) {}
let vibe = null;
if (wx) {
  const c = wx.cond.toLowerCase();
  vibe = c.includes('rain') ? 'wet and moody' : c.includes('snow') ? 'cold and wintry'
    : wx.temp <= 40 ? 'chilly' : wx.temp <= 55 ? 'cool' : wx.temp <= 70 ? 'comfortable' : wx.temp <= 85 ? 'warm' : 'hot';
}

// --- song hygiene (same rules that keep ads and sweepers off Marcus's sheet) ---
const aliases = { 'Daryl Hall & John Oates': 'Hall and Oates', 'Daryl Hall and John Oates': 'Hall and Oates', 'Earth, Wind & Fire': 'Earth Wind and Fire', 'Crosby, Stills, Nash & Young': 'CSNY' };
const cleanTitle = (t) => String(t || '').split(/\s+-\s+/)[0].replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim();
const isBumper = (title, artist, duration) => {
  const t = String(title || '').toLowerCase();
  const a = String(artist || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const dur = Number(duration) || 0;
  if (dur > 0 && dur < 90) return true;
  if (!a) return true;
  if (a.replace(/\s+/g, '') === 'live365') return true;
  if (['mellow mountain radio', 'station id', 'app announcement'].includes(a)) return true;
  return /adbreak|ad break|sweeper|imaging|bumper|station id|\bliner\b|\bpromo\b|\bident\b/.test(t);
};
const recent = [];
try {
  const np = $('Ask the airwaves').first().json || {};
  for (const r of (np.song_history || [])) {
    const s = r && r.song;
    if (!s || !s.title) continue;
    if (isBumper(s.title, s.artist, r.duration)) continue;
    const title = cleanTitle(s.title);
    if (!title || title.toLowerCase() === 'mellow mountain radio') continue;
    recent.push({ title: title.slice(0, 120), artist: aliases[s.artist] || String(s.artist || '').slice(0, 120) });
    if (recent.length >= 5) break;
  }
} catch (e) {}

// --- controlled songs: only trusted when the playlist WILL be written ---
let nextSongs = [], leadSong = null;
try {
  const pj = $('Pick the rotation songs').first().json || {};
  if (pj.voReady) { nextSongs = pj.picks || []; leadSong = pj.leadIn || null; }
} catch (e) {}

// --- events / shows / movies from the mellowmountainradio.com site feeds ---
const dstr = (dt) => dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate());
const localHorizon = new Date(phx); localHorizon.setDate(localHorizon.getDate() + 21);
const showHorizon = new Date(phx); showHorizon.setDate(showHorizon.getDate() + 60);
const movieHorizon = new Date(phx); movieHorizon.setDate(movieHorizon.getDate() + 14);
const localH = dstr(localHorizon), showH = dstr(showHorizon), movieH = dstr(movieHorizon);
const VERDE = new Set(['sedona', 'village of oak creek', 'cottonwood', 'clarkdale', 'jerome', 'camp verde', 'flagstaff']);
const feed = (nodeName) => {
  try {
    const j = $(nodeName).first().json || {};
    return typeof j.data === 'string' ? JSON.parse(j.data) : j;
  } catch (e) { return {}; }
};
const pickFrom = (arr, n) => arr.length ? (arr[0].rank === 0 ? arr[0] : arr[Math.floor(Math.random() * Math.min(n, arr.length))]) : null;

const localPool = [];
try {
  const lib = feed('Fetch library events');
  for (const e of (lib.events || [])) {
    if (!e || !e.date || e.date < today || e.date > localH) continue;
    localPool.push({ date: e.date, name: e.title, place: 'the Community Library in Sedona', note: e.time ? ('starts ' + e.time) : '', rank: 1 });
  }
} catch (e) {}
localPool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
const evLocal = pickFrom(localPool, 4);

const showPool = [];
try {
  const con = feed('Fetch concerts');
  for (const s of (con.concerts || [])) {
    if (!s || s.state !== 'AZ' || !s.date || s.date < today || s.date > showH) continue;
    const near = VERDE.has(String(s.city || '').toLowerCase());
    showPool.push({ date: s.date, name: (aliases[s.artist] || s.artist) + ' at ' + s.venue, place: s.city + ', Arizona', rank: near ? 0 : 1 });
  }
} catch (e) {}
try {
  const fes = feed('Fetch festivals');
  for (const f of (fes.festivals || [])) {
    const fd = f && f.start;
    if (!f || f.state !== 'AZ' || !fd || fd < today || fd > showH) continue;
    const near = VERDE.has(String(f.city || '').toLowerCase());
    showPool.push({ date: fd, name: f.name, place: f.city + ', Arizona', rank: near ? 0 : 1 });
  }
} catch (e) {}
showPool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
const evShow = pickFrom(showPool, 5);

const moviePool = [];
try {
  const st = feed('Fetch showtimes');
  for (const m of (st.showings || [])) {
    if (!m || !m.date || m.date < today || m.date > movieH) continue;
    const near = VERDE.has(String(m.city || '').toLowerCase());
    moviePool.push({ date: m.date, time: m.time || '', title: m.title, venue: m.venue, place: m.city, rank: near ? 0 : 1 });
  }
} catch (e) {}
moviePool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
const evMovie = moviePool.length ? moviePool[Math.floor(Math.random() * Math.min(5, moviePool.length))] : null;

// --- daypart song quota: at least 3 lead-in/lead-out song breaks per shift ---
// Only counts breaks where the playlist is actually controlled (voReady), so a
// back-announce or tease is guaranteed true on air. Resets each day per DJ.
const controlled = !!(leadSong || nextSongs.length);
const onShift = !!(slot && hour >= slot.from && hour <= slot.to);
if (slot && mem.shiftKey !== today) { mem.shiftKey = today; mem.shiftSongs = 0; }
const songsDone = slot ? (mem.shiftSongs || 0) : 0;
const songsNeeded = slot ? Math.max(0, 3 - songsDone) : 0;
const breaksLeft = onShift ? (slot.to - hour + 1) : 0;
const forceSong = !!(onShift && controlled && songsNeeded > 0 && breaksLeft <= songsNeeded);
// First break of the shift is the DJ's shift-opening intro.
const shiftOpen = onShift && hour === slot.from;
const shiftSpan = slot ? (slot.from < 12 ? 'the morning, right through till noon' : slot.from < 18 ? 'the whole afternoon' : 'the evening, all the way to midnight') : '';

// --- the director: one fresh lead angle per break, per-DJ memory ---
let weatherMode = ['exact', 'descriptive', 'mixed'][Math.floor(Math.random() * 3)];
const mSelfID = shiftOpen || Math.random() < (profile.selfIdRate != null ? profile.selfIdRate : 0.4);
const nightish = (bucket === 'overnight' || bucket === 'late night' || bucket === 'early morning');
const drive = (bucket === 'morning drive' || bucket === 'afternoon' || bucket === 'late afternoon');

const siteSpotlights = [
  { name: 'Chakras & Tarot', hook: 'the full seventy-eight-card tarot with a card of the day drawn over Sedona, plus the seven chakras and their healing frequencies' },
  { name: 'Sound Healing', hook: 'the KAZM Harmonic Stack — binaural tone sessions and a coherent-breathing pacer, all synthesized live right in your browser' },
  { name: 'Astrology', hook: 'daily readings drawn from the real sky over Sedona, live planet positions, and your own Sun, Moon and Rising birth chart' },
  { name: 'Cosmic Conditions', hook: "Sedona's vortex energy and tonight's cosmic weather — the moon phase, the geomagnetic field, and the Earth's Schumann resonance" },
  { name: 'the Song Time Machine', hook: 'every song we play logged the moment it airs — look up what was on at any minute, or browse the weekly spin charts' },
  { name: "the Listeners' Lounge", hook: 'every broadcast hour of KAZM kept for two weeks and ready to replay, so you never miss a moment' },
  { name: 'the Jeep Trails guide', hook: 'every legendary Sedona trail — Broken Arrow, Soldier Pass, Schnebly Hill — with live run-verdicts and a last-safe-start clock' },
  { name: 'Events and Adventures', hook: 'live trail conditions, the Oak Creek flow, Slide Rock, the ski report, even geocaching spots to get you outside' },
  { name: 'Seen around Sedona', hook: 'a living field guide to the Verde Valley — live wildlife sightings and what is blooming right now' },
  { name: 'Contests', hook: 'Ticket Tuesday, Food Fridays, and more giveaways' },
  { name: 'the Photography guide', hook: "a photographer's guide to shooting the red rocks" },
  { name: 'the Music page', hook: "the artists in rotation and the three o'clock three pack" },
  { name: 'Podcasts', hook: 'station shows and podcasts on demand, any time you want them' },
];

// Daypart DJs: song breaks are always real lead-in/lead-out breaks (quota 3
// per shift, weight 0 once met); no pure-reflection breaks — the rest of the
// pool is weather with real temps, local events, concerts, movies, website.
const angleDefs = {
  weather:    { avail: !!wx,               w: bucket === 'early morning' ? 3 : drive ? 3 : 2 },
  song:       { avail: (recent.length > 0 || nextSongs.length > 0 || !!leadSong), w: slot ? (!shiftOpen && controlled && songsNeeded > 0 ? 4 : 0) : 2 },
  local:      { avail: !!evLocal,          w: 2 },
  concert:    { avail: !!evShow,           w: 2 },
  movie:      { avail: !!evMovie,          w: 2 },
  website:    { avail: true,               w: nightish ? 3 : 2 },
  reflection: { avail: !slot,              w: nightish ? 3 : 1 },
};
mem.recentAngles = mem.recentAngles || [];
const buildBag = (exclude) => {
  const bag = [];
  for (const k of Object.keys(angleDefs)) {
    if (!angleDefs[k].avail || exclude.has(k)) continue;
    for (let i = 0; i < angleDefs[k].w; i++) bag.push(k);
  }
  return bag;
};
const excl = new Set(mem.recentAngles);
// Daypart DJs need song breaks about every other hour to hit the quota, so
// only block back-to-back songs instead of the full 3-break memory.
if (slot && mem.recentAngles[mem.recentAngles.length - 1] !== 'song') excl.delete('song');
let bag = buildBag(excl);
if (!bag.length) bag = buildBag(new Set());
const primary = forceSong ? 'song' : (bag.length ? bag[Math.floor(Math.random() * bag.length)] : 'reflection');
mem.recentAngles.push(primary);
if (mem.recentAngles.length > 3) mem.recentAngles = mem.recentAngles.slice(-3);
let secondary = null;
if (Math.random() < 0.30) {
  const secBag = buildBag(new Set([primary, 'song', 'reflection']));
  if (secBag.length) secondary = secBag[Math.floor(Math.random() * secBag.length)];
}
const angleSet = new Set([primary, secondary].filter(Boolean));

const mWeather = angleSet.has('weather');
const mSong = angleSet.has('song');
let songKind = null, songData = null;
if (mSong) {
  if (leadSong && nextSongs.length) {
    const r = Math.random();
    songKind = r < 0.4 ? 'bracket' : r < 0.75 ? 'next' : 'lead';
  }
  else if (nextSongs.length) { songKind = 'next'; }
  else if (leadSong) { songKind = 'lead'; }
  else if (recent.length) { songKind = 'recent'; songData = recent[Math.floor(Math.random() * Math.min(3, recent.length))]; }
}
const mVibe = songKind === 'recent';
const mNext = songKind === 'next' || songKind === 'bracket';
const mLead = songKind === 'lead' || songKind === 'bracket';
// Count real lead-in/lead-out song breaks toward the shift quota.
if (slot && primary === 'song' && (mLead || mNext)) mem.shiftSongs = (mem.shiftSongs || 0) + 1;
// Daypart DJs give real numbers when weather leads ("specific temps").
if (slot && angleSet.has('weather')) weatherMode = primary === 'weather' ? 'exact' : 'mixed';
const mLocal = angleSet.has('local');
const mShow = angleSet.has('concert');
const mMovie = angleSet.has('movie');
const mSite = angleSet.has('website');
const mReflect = primary === 'reflection' && !secondary;

mem.spotlights = mem.spotlights || [];
let spotlight = null;
if (mSite) {
  const freshS = siteSpotlights.filter((s) => !mem.spotlights.includes(s.name));
  const poolS = freshS.length ? freshS : siteSpotlights;
  spotlight = poolS[Math.floor(Math.random() * poolS.length)];
  mem.spotlights.push(spotlight.name);
  if (mem.spotlights.length > 6) mem.spotlights = mem.spotlights.slice(-6);
}

const openings = (mem.scripts || []).slice(-4).map((s) => s.opening).filter(Boolean);

// --- compose the system prompt: roster persona + the engine's shared rules ---
// The shift-open show welcome runs long (30-60 seconds) for every DJ.
const wr = shiftOpen ? (profile.introWordRange || [90, 150]) : (profile.wordRange || [70, 90]);
const secs = Math.round(((wr[0] + wr[1]) / 2) / 2.7);
const tagRule = profile.audioTags
  ? '- This voice supports ElevenLabs v3 audio tags: you may use one to three tags like [laughing], [excited], [cheerful], [sighs] where they genuinely fit the delivery. Tags are performance directions in square brackets, never spoken words. Do not overuse them, and use no other brackets.'
  : '- Output spoken words only. No stage directions, brackets, audio tags, quotes around the whole thing, emojis, markdown, or explanations.';
const stationRule = profile.stationIdLine
  ? '- Include this exact station ID line once, naturally placed: "' + profile.stationIdLine + '"'
  : '- End by mentioning Mellow Mountain Radio, once, naturally.';

const timeRule = slot
  ? 'You may casually reference the day and part of day when it fits ("this Tuesday afternoon", "on a bright Sedona morning", "tonight") — but never read out a precise clock time. Never sound rushed overnight, never sound sleepy during drive times.'
  : 'Strict: never mention the time or time ranges on air — let tone imply the time. Never sound rushed overnight, never sound sleepy during drive times.';
const system = profile.persona
  + '\n\nTIME-BASED DELIVERY\n\nAdjust tone, pacing, and energy to the provided timeBucket: overnight and late night are low-key, calm, quiet company at a very relaxed pace; early morning is gentle and welcoming with short sentences; morning drive is upbeat, confident, fully awake with light humor; late morning and midday are bright, smooth, friendly; afternoon and late afternoon are easygoing cruising energy; evening is warm and companionable, readier to crack a joke.\n' + timeRule
  + '\n\nWEATHER EXPRESSION\n\nWhen weather is listed with a mode, use it. EXACT: precise temperature and conditions. DESCRIPTIVE: no numbers, just how it feels. MIXED: descriptive phrasing with a light numeric touch ("sitting in the mid-40s"). Match weather tone to the hour; overnight and early morning favor descriptive or mixed.'
  + '\n\nSONG & ARTIST\n\nWhen mentioned, be casual — never a formal announcement. Use spoken artist names as given. Keep titles short. A song listed as playing right before this break fades out just as you come on — back-announce it in past tense, like it is still hanging in the air. Songs listed as coming up are locked into the playout and guaranteed to play — tease them as on the way. Other earlier songs are past tense, about how they FELT. If no coming-up song is listed, never name one; at most say more music is on the way. No artist trivia, biography, or chart history — never facts about the music. If uncertain, be safely vague.'
  + '\n\nHARD RULES — break any of these and the break does not air:\n'
  + tagRule + '\n'
  + '- Build the break around the ANGLE stated below, using ONLY the facts listed. Never invent weather numbers, songs, artists, events, times, places, or website features. If a subject is not listed, it does not exist for this break — leave it out entirely.\n'
  + '- Length: ' + wr[0] + ' to ' + wr[1] + ' words (about ' + secs + ' seconds read aloud). Short sentences, written for the ear. Say numbers and dates the way people speak them.\n'
  + '- Vary your openings: never start like any recently used opening listed, and avoid stock DJ lines ("you are listening to" is allowed only inside the required station ID line, if one is given).\n'
  + stationRule + '\n'
  + '- Never mention being an AI, a script, or anything behind the curtain. You are this DJ. Full stop.';

const evWhen = (dt) => dt === today ? 'today' : (dt === dstr(new Date(phx.getFullYear(), phx.getMonth(), phx.getDate() + 1)) ? 'tomorrow' : daysN[new Date(dt + 'T12:00:00').getDay()] + ' (' + dt + ')');

const angleText = {
  weather: 'Lead with the Sedona weather and sky right now.',
  song: 'Lead with the music. The sheet may list the song playing right before this break (back-announce it — it fades out just as you come on), the songs coming up right after (tease as on the way), or one played a little earlier (past tense). Use what is listed. Talk about how the music FEELS, never a formal announcement.',
  local: 'Lead with the local Sedona happening listed below.',
  concert: 'Lead with the upcoming Arizona show listed below — something to look forward to.',
  movie: 'Lead with the film screening listed below.',
  website: 'Lead with the website feature listed below — make the listener want to open mellowmountainradio.com.',
  reflection: 'No outside facts this time — just you. A short, warm piece of company: a thought, a feeling, the hour, the valley. Do NOT mention weather, songs, events, shows, movies, or the website — none of that exists for this break.',
};

const lines = [];
lines.push('Current local time: ' + clock + ' on ' + weekday + '. timeBucket: ' + bucket + '.');
lines.push('');
if (shiftOpen) {
  lines.push('SHIFT OPEN — this is your FIRST break of today\'s shift: your show open, and it runs longer than a normal break (use the full length). Welcome listeners properly: greet Sedona and the Verde Valley, introduce yourself by name, and tell them you\'re with them for the next six hours — ' + shiftSpan + '. Sell the ride ahead: great music lined up, hit after hit, they\'re in for a treat — in YOUR OWN words and your own personality, and never phrased like any recent opening listed below; make today\'s welcome feel brand new. Make it feel like walking into the studio, settling in, glad to be here. Weave the angle below into the welcome as your opening subject.');
  lines.push('');
}
lines.push('ANGLE FOR THIS BREAK: ' + (angleText[primary] || primary));
if (secondary) lines.push('SECONDARY (one light touch only, keep it under the lead): ' + (angleText[secondary] || secondary));
lines.push('');
lines.push('FACTS YOU MAY USE (only these exist — invent nothing else):');
let any = false;
if (mWeather) { lines.push('- Weather in Sedona right now: ' + wx.cond + ', ' + wx.temp + ' degrees (feels ' + vibe + '). Weather mode: ' + weatherMode + '.'); any = true; }
if (mVibe && songData) { lines.push('- Played a little earlier (past tense, how it FELT): "' + songData.title + '" by ' + songData.artist + '.'); any = true; }
if (mLead && leadSong) { lines.push('- Playing right before this break (it fades out just as you come on — back-announce it, past tense): "' + leadSong.title + '" by ' + leadSong.artist + '.'); any = true; }
if (mNext && nextSongs.length) { lines.push('- Coming up right after this break (locked in — tease as on the way): ' + nextSongs.slice(0, 2).map((s) => '"' + s.title + '" by ' + s.artist).join(', then ') + '.'); any = true; }
if (mLocal && evLocal) { lines.push('- Local Sedona happening: ' + evLocal.name + (evLocal.place ? ' at ' + evLocal.place : '') + ', ' + evWhen(evLocal.date) + (evLocal.note ? ' — ' + evLocal.note : '') + '.'); any = true; }
if (mShow && evShow) { lines.push('- Upcoming Arizona show: ' + evShow.name + ', ' + evShow.place + ', ' + evWhen(evShow.date) + '.'); any = true; }
if (mMovie && evMovie) { lines.push('- On a Sedona screen: "' + evMovie.title + '" at ' + evMovie.venue + (evMovie.place ? ', ' + evMovie.place : '') + ', ' + evWhen(evMovie.date) + (evMovie.time ? ' at ' + evMovie.time : '') + '. Full showtimes live at mellowmountainradio.com.'); any = true; }
if (mSite && spotlight) { lines.push('- Website feature: mellowmountainradio.com has ' + spotlight.name + ' — ' + spotlight.hook + '. Invite the listener to explore it.'); any = true; }
if (!any) lines.push('- (none — this is a mood break; state no facts, invent nothing.)');
lines.push('');
lines.push('SELF-ID: ' + (mSelfID ? 'YES — say your on-air name this break: work in "' + (profile.selfIdName || profile.name) + '" naturally, ' + (shiftOpen ? 'early — this is your shift-opening introduction.' : 'usually in the sign-off.') : 'NO — no need to say your own name this break.'));
lines.push('');
lines.push('Recently used openings (do NOT start like any of these): ' + (openings.length ? openings.join(' | ') : 'none yet') + '.');
lines.push('');
lines.push('TASK: Write ONE fresh DJ break built on the ANGLE above.');

return [{ json: { system, user: lines.join('\n'), meta: { dj: djId, bucket, clock, weatherMode, primary, secondary, shiftOpen, quota: { onShift, controlled, songsDone: slot ? mem.shiftSongs || 0 : null, breaksLeft, forceSong }, flags: { mWeather, mSong, mVibe, mNext, mLead, mLocal, mShow, mMovie, mSite, mReflect, mSelfID } } } }];

// Last line of defense before the voice booth — profile-aware.
const profile = $('Select the DJ').first().json.profile;
const r = $input.first().json || {};
let text = '';
try {
  const blocks = Array.isArray(r.content) ? r.content : [];
  const tb = blocks.find((b) => b && b.type === 'text');
  if (tb) text = tb.text;
} catch (e) {}
if (!text && typeof r.text === 'string') text = r.text;
text = String(text || '').trim();
if (!text) throw new Error('No script came back from the DJ brain');
if (!profile.audioTags) text = text.replace(/\[[^\]]*\]/g, ' ');
text = text.replace(/^["'“‘]+|["'’”]+$/g, '');
text = text.replace(/[*_#>`]+/g, ' ');
text = text.replace(/\s+/g, ' ').trim();
for (const bad of [/as an ai/i, /language model/i, /\bfact sheet\b/i, /\bmention flag/i, /angle for this break/i, /\bself-id\b/i, /\btimebucket\b/i]) {
  if (bad.test(text)) throw new Error('Script leaked something off-air: ' + text.slice(0, 80));
}
const spoken = text.replace(/\[[^\]]*\]/g, ' ').replace(/\s+/g, ' ').trim();
const words = spoken.split(' ').length;
const minWords = Math.max(15, Math.round(((profile.wordRange || [70, 90])[0]) * 0.6));
if (words < minWords) throw new Error('Script came back too short to air: ' + text);
return [{ json: { script: text, words, opening: spoken.split(' ').slice(0, 7).join(' ') } }];

// Per-DJ logbook in staticData.
const sd = $getWorkflowStaticData('global');
const sel = $('Select the DJ').first().json;
sd.djs = sd.djs || {};
const mem = sd.djs[sel.djId] = sd.djs[sel.djId] || {};
mem.scripts = mem.scripts || [];
const c = $('Clean the copy').first().json;
mem.scripts.push({ at: new Date().toISOString(), words: c.words, opening: c.opening, script: c.script });
if (mem.scripts.length > 40) mem.scripts = mem.scripts.slice(-40);
return [{ json: { saved: true, dj: sel.djId, words: c.words } }];

// Read a DJ's last ten scripts: .../webhook/kazm-dj-log?k=moon-2026&dj=burt
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
if (q.k !== 'moon-2026') return [{ json: { ok: false, why: 'bad key' } }];
const dj = String(q.dj || '').toLowerCase().trim();
const djs = sd.djs || {};
if (!dj) return [{ json: { ok: true, djs: Object.keys(djs) } }];
const mem = djs[dj] || {};
return [{ json: { ok: true, dj, scripts: (mem.scripts || []).slice(-10).reverse() } }];

// The engine as daytime music director: pick a lead-in song plus three
// after-break songs from the station's rotation categories, weighted the way
// rotation is meant to work. Also look up this DJ's break file in the MegaSeg
// library — song control only turns on once the file exists there (voReady).
//
// Picks must survive MegaSeg's Playlist Rules untouched (artist separation
// 30 min, title separation 30 min, no same-hour-as-yesterday), otherwise
// MegaSeg substitutes songs and the DJ's back-announce/tease becomes wrong.
// Every pick is screened against those rules with margin to spare.
const sd = $getWorkflowStaticData('global');
const sel = $('Select the DJ').first().json;
const profile = sel.profile;
const djId = sel.djId;

// Only the daypart DJs drive their MegaSeg VO playlists.
const DAYPART_DJS = ['burt', 'canyonjack', 'kaley'];

let raw = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} catch (e) {}

const CATS = [
  { name: '* A.  HEAVY ROTATION', w: 0.6 },
  { name: '***** B.  MEDIUM ROTATION', w: 0.3 },
  { name: '********* C. LOW ROTATION', w: 0.1 },
];

const cleanT = (t) => String(t || '').split(/\s+-\s+/)[0].replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
const cleanA = (a) => String(a || '').trim().replace(/\s+/g, ' ').toLowerCase();

// what's been on the air lately (titles AND artists), from AzuraCast
const recentTitles = new Set();
const hotArtists = new Set(); // artists heard on air within the last hour
const nowSec = Math.floor(Date.now() / 1000);
try {
  const np = $('Ask the airwaves').first().json || {};
  const nowS = np.now_playing && np.now_playing.song;
  if (nowS && nowS.title) recentTitles.add(cleanT(nowS.title));
  if (nowS && nowS.artist) hotArtists.add(cleanA(nowS.artist));
  for (const r of (np.song_history || []).slice(0, 20)) {
    if (!r || !r.song) continue;
    if (r.song.title) recentTitles.add(cleanT(r.song.title));
    if (r.song.artist && r.played_at && nowSec - r.played_at < 3600) hotArtists.add(cleanA(r.song.artist));
  }
} catch (e) {}
sd.rotationScheduled = sd.rotationScheduled || [];
const recentIds = new Set(sd.rotationScheduled);

// MegaSeg "15] Last Played" — Mac-local time like "12/9/25 4:53 PM"
const parseLP = (s) => {
  const m = String(s || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})\s+(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return null;
  let yr = Number(m[3]); if (yr < 100) yr += 2000;
  let h = Number(m[4]) % 12; if (/pm/i.test(m[6])) h += 12;
  return new Date(yr, Number(m[1]) - 1, Number(m[2]), h, Number(m[5]));
};
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const airHour = now.getHours(); // generated at :16, airs at :20 the same hour
const yd = new Date(now); yd.setDate(yd.getDate() - 1);

// parse the MegaSeg Database
const pools = { 0: [], 1: [], 2: [] };
let voRec = null;
const artistLast = {}; // artist -> most recent Last Played across the WHOLE library
// this DJ's break file as a Mac-classic location suffix, e.g. ":DJ Breaks:Burt Break.mp3"
const macSuffix = ':' + String(profile.dropboxPath || '').split('/').filter(Boolean).slice(1).join(':');
if (raw.startsWith('D**')) {
  for (const rec of raw.split('99* ----').slice(1)) {
    const f = {};
    for (const line of rec.split('\n')) {
      const m = line.match(/^(\d\d)\]\s?(.*)$/);
      if (m) f[m[1]] = m[2].replace(/\r$/, '');
    }
    if (!f['49']) continue;
    if (macSuffix.length > 1 && f['49'].endsWith(macSuffix)) voRec = f;
    const a = cleanA(f['02']);
    const lp = parseLP(f['15']);
    if (a && lp && (!artistLast[a] || lp > artistLast[a])) artistLast[a] = lp;
    if (!f['01'] || !f['45']) continue;
    const segs = String(f['06'] || '').split('/');
    for (let i = 0; i < CATS.length; i++) {
      if (segs.includes(CATS[i].name)) { pools[i].push(f); break; }
    }
  }
}

// MegaSeg-rule screen — these filters are NEVER relaxed:
// - not played in the last 90 min (title separation is 30; wide margin)
// - not played yesterday during this same clock hour
// - artist not already in this block, not on air in the last hour, and no
//   song of theirs played in the last 60 min (artist separation is 30)
const ruleSafe = (f, usedArtists, usedTitles) => {
  const a = cleanA(f['02']);
  const t = cleanT(f['01']);
  const lp = parseLP(f['15']);
  if (lp) {
    if (now - lp < 90 * 60 * 1000) return false;
    if (lp.getFullYear() === yd.getFullYear() && lp.getMonth() === yd.getMonth() && lp.getDate() === yd.getDate() && lp.getHours() === airHour) return false;
  }
  if (t && usedTitles.has(t)) return false;
  if (a) {
    if (usedArtists.has(a) || hotArtists.has(a)) return false;
    const al = artistLast[a];
    if (al && now - al < 60 * 60 * 1000) return false;
  }
  return true;
};

const toSecs = (t) => {
  const p = String(t || '').split(':').map(Number);
  if (p.some(isNaN) || !p.length) return 0;
  return p.reduce((a, b) => a * 60 + b, 0);
};
const toRow = (f) => {
  const cols = new Array(25).fill('');
  cols[0] = f['01']; cols[1] = f['02'] || ''; cols[3] = f['09'] || '';
  cols[4] = String(f['06'] || '').split('/')[0];
  cols[6] = toSecs(f['05']).toFixed(2);
  cols[11] = f['10'] || ''; cols[20] = f['14'] || '0'; cols[21] = f['15'] || '';
  cols[22] = '0'; cols[23] = f['49']; cols[24] = f['45'];
  return cols.join('\t');
};

// weighted pick: roll a rotation tier, then a fresh rule-safe song within it.
// Freshness (recentTitles / no-repeat memory) can relax; ruleSafe never does.
const pickOne = (used, usedArtists, usedTitles) => {
  for (let attempt = 0; attempt < 12; attempt++) {
    const r = Math.random();
    const tier = r < CATS[0].w ? 0 : r < CATS[0].w + CATS[1].w ? 1 : 2;
    const safe = pools[tier].filter((f) => !used.has(f['45']) && ruleSafe(f, usedArtists, usedTitles));
    let cands = safe.filter((f) => !recentTitles.has(cleanT(f['01'])) && !recentIds.has(f['45']));
    if (!cands.length) cands = safe.filter((f) => !recentIds.has(f['45']));
    if (!cands.length) cands = safe;
    if (!cands.length) continue;
    return cands[Math.floor(Math.random() * cands.length)];
  }
  return null;
};

const voReady = DAYPART_DJS.includes(djId) && !!voRec;
let leadPick = null, nextPicks = [];
if (voReady) {
  const used = new Set(), usedArtists = new Set(), usedTitles = new Set();
  const chosen = [];
  while (chosen.length < 4) {
    const f = pickOne(used, usedArtists, usedTitles);
    if (!f) break;
    used.add(f['45']);
    const a = cleanA(f['02']); if (a) usedArtists.add(a);
    const t = cleanT(f['01']); if (t) usedTitles.add(t);
    chosen.push(f);
  }
  if (chosen.length >= 2) { leadPick = chosen[0]; nextPicks = chosen.slice(1); }
  else nextPicks = chosen;
  for (const f of chosen) sd.rotationScheduled.push(f['45']);
  if (sd.rotationScheduled.length > 60) sd.rotationScheduled = sd.rotationScheduled.slice(-60);
}

return [{ json: {
  voReady,
  poolSizes: [pools[0].length, pools[1].length, pools[2].length],
  leadIn: leadPick ? { title: leadPick['01'], artist: leadPick['02'] || '' } : null,
  picks: nextPicks.map((f) => ({ title: f['01'], artist: f['02'] || '' })),
  leadRow: leadPick ? toRow(leadPick) : null,
  rows: nextPicks.map(toRow),
  voRow: voRec ? toRow(voRec) : null,
} }];

// Rebuild THIS DJ's MegaSeg VO playlist (e.g. "Burt DJ VO"): lead-in song ->
// this DJ's fresh VO -> three exact songs. MegaSeg Events insert the playlist
// matching the daypart, and the regular daytime queue resumes afterward.
const HEADER = 'Name\tArtist\tComposer\tAlbum\tGenre\tSize\tTime\tDisc Number\tDisc Count\tTrack Number\tTrack Count\tYear\tDate Modified\tDate Added\tBit Rate\tSample Rate\tVolume Adjustment\tKind\tEqualizer\tComments\tPlays\tLast Played\tMy Rating\tLocation\tUniqueID';
const pj = $('Pick the rotation songs').first().json;
const profile = $('Select the DJ').first().json.profile;
const playlistName = profile.playlistName || (profile.name + ' DJ VO');
const lines = [HEADER];
if (pj.leadRow) lines.push(pj.leadRow);
lines.push(pj.voRow);
for (const r of (pj.rows || [])) lines.push(r);
return [{ json: { playlistContent: lines.join('\n') + '\n', songCount: (pj.rows || []).length + (pj.leadRow ? 1 : 0), playlistName } }];

// Pick a random bed from the DJ Beds folder; daypart DJs only.
const djId = $('Select the DJ').first().json.djId;
const DAYPART_DJS = ['burt', 'canyonjack', 'kaley'];
const vf = '/tmp/kazm-vo-' + djId + '.mp3';
const bf = '/tmp/kazm-bed-' + djId + '.mp3';
const of = '/tmp/kazm-mix-' + djId + '.mp3';
let beds = [];
try {
  beds = $input.all().map((i) => i.json).filter((j) => j && j.name && /\.(mp3|m4a|wav|aif|aiff)$/i.test(j.name) && j.type !== 'folder' && j['.tag'] !== 'folder');
} catch (e) {}
const pick = beds.length ? beds[Math.floor(Math.random() * beds.length)] : null;
const doMix = DAYPART_DJS.includes(djId) && !!pick;
return [{ json: { doMix, bedPath: pick ? (pick.path_display || pick.path_lower || ('/Charles Helstein/DJ Beds/' + pick.name)) : '', bedName: pick ? pick.name : null, voiceFile: vf, bedFile: bf, outFile: of } }];

// Use the mixed file when the mix chain produced one; otherwise the dry voice.
let mixedFlag = false;
try { mixedFlag = String($('Mix the bed').first().json.stdout || '').includes('MIXED'); } catch (e) {}
let out = null;
try {
  const m = $('Load the mix').first();
  if (m && m.binary && m.binary.data) out = { json: { mixed: mixedFlag, bed: $('Pick a bed').first().json.bedName }, binary: m.binary };
} catch (e) {}
if (!out) out = { json: { mixed: false }, binary: $('Voice the break').first().binary };
return [out];
